pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount1, uint256 amount2) public {
        vm.assume(amount1 >= 1 ether);
        vm.assume(amount2 >= 1 ether);
        ReentrantAttacker attacker = new ReentrantAttacker(c);
        vm.deal(address(attacker), amount1 + amount2 + 1 ether);
        attacker.attack{value: amount1 + amount2}();
        assertEq(address(c).balance, amount1 + amount2);
    }
}

contract ReentrantAttacker {
    C public target;
    uint256 public count;
    constructor(C _target) { target = _target; }
    function attack() external payable {
        target.Put{value: msg.value}(0);
    }
    receive() external payable {
        if (count == 0) {
            count++;
            target.Put{value: address(this).balance}(0);
        }
