// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    ReentrantAttacker attacker;

    function setUp() public {
        c = new C(address(this));
        attacker = new ReentrantAttacker(address(c));
        vm.deal(address(attacker), 10 ether);
    }

    function testFuzz_property(uint256 unlockTime) public {
        // Ensure unlock time is in the future so Collect is allowed after Put
        vm.assume(unlockTime > block.timestamp);
        // Keep unlock time reasonable to ensure Collect check passes
        vm.assume(unlockTime < block.timestamp + 365 days);

        // Record initial ETH balance of the contract
        uint256 initialBalance = address(c).balance;
        // Attacker puts 1 ether and triggers reentry during Put
        attacker.attack{value: 1 ether}(unlockTime);

        // After the attack, contract ETH should never decrease if reentry guard worked
        // Reference: guard prevents reentry, so ETH stays >= initialBalance + 1 ether (the deposited amount)
        // Bug: no guard allows reentry via Collect, leaving ETH strictly less than initialBalance + 1 ether
        assertTrue(address(c).balance >= initialBalance + 1 ether);
    }
}

contract ReentrantAttacker {
    C public target;
    bool private attacking;
    uint private unlockTime;

    constructor(address _target) {
        target = C(_target);
    }

    function attack(uint _unlockTime) external payable {
        unlockTime = _unlockTime;
        attacking = true;
        target.Put{value: msg.value}(unlockTime);
        attacking = false;
    }

    receive() external payable {
        if (attacking && address(target).balance >= 1 ether) {
            target.Collect(1 ether);
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 amount1, uint256 amount2, uint256 unlockTime) public {
        vm.assume(amount1 > 0 && amount2 > 0);
        // Deploy a re-entrant caller that triggers Put via fallback during Put
        ReEntrantAttacker attacker = new ReEntrantAttacker(address(c));
        vm.deal(address(attacker), amount1 + amount2);

        // Call Put with the first amount; the attacker's fallback will call Put again with the second amount
        attacker.initiate(amount1, amount2, unlockTime);

        // The property: after all calls, locked_ must be false.
        // locked_ is a state variable of sGuard which is inherited by C, but it's internal with no getter.
        // However, we can infer the lock state by attempting a no-op call that requires the lock to be free.
        // A successful call implies locked_ is false; a revert implies locked_ is true.
        bool unlocked;
        try c.Put(0) { unlocked = true; } catch { unlocked = false; }
        assertTrue(unlocked);
    }
}

contract ReEntrantAttacker {
    C target;
    uint256 private secondAmount;
    uint256 private unlockTime;
    bool private isFirstCall;

    constructor(address _target) {
        target = C(payable(_target));
        isFirstCall = true;
    }

    function initiate(uint256 amount1, uint256 amount2, uint256 _unlockTime) external payable {
        secondAmount = amount2;
        unlockTime = _unlockTime;
        target.Put{value: amount1}(_unlockTime);
    }

    fallback() external payable {
        if (isFirstCall) {
            isFirstCall = false;
            target.Put{value: secondAmount}(unlockTime);
        }
    }
}

