pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 depositAmount, uint256 unlockTime) public {
        // Bound inputs to admissible range: depositAmount > 0 and unlockTime in the future
        depositAmount = bound(depositAmount, 1, 100 ether);
        unlockTime = bound(unlockTime, block.timestamp + 1, block.timestamp + 365 days);

        // Deploy a re-entrant attacker contract
        ReentrantAttacker attacker = new ReentrantAttacker(c);
        address attackerAddr = address(attacker);

        // Fund attacker
        vm.deal(attackerAddr, depositAmount);

        // Attacker deposits via Put, which will re-enter and call Collect internally
        vm.prank(attackerAddr);
        attacker.attack{value: depositAmount}(unlockTime);

        // After the attack, check the invariant: internal balance should equal total deposited minus withdrawn
        // In the buggy version, the internal balance is not properly updated during re-entrant Collect,
        // so it will be less than expected (i.e., > 0 when it should be 0 after a full withdraw).
        uint256 balance = c.Acc(attackerAddr).balance;
        assertTrue(balance == 0);
    }
}

contract ReentrantAttacker {
    C public target;
    uint256 private unlockTime;
    bool private attacking;

    constructor(C _target) {
        target = _target;
    }

    function attack(uint256 _unlockTime) external payable {
        unlockTime = _unlockTime;
        attacking = true;
        target.Put(unlockTime);
        attacking = false;
    }

    fallback() external payable {
        if (attacking) {
            attacking = false;
            // Re-enter via Collect to withdraw funds
            target.Collect(msg.value);
        }
    }
}

