        vm.assume(amount >= 1 ether);
        vm.assume(amount <= address(this).balance / 2);

        // Grab initial contract balance
        uint256 initContractBal = address(c).balance;

        // Actor sends Put with value
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(0);

        // Grab final contract balance and sum of Acc balances
        uint256 finalContractBal = address(c).balance;
        uint256 balance1 = c.Acc(actor).balance;
        uint256 sumBalances = balance1;

        // For the reference, contract balance increased by amount, and sum of Acc[actor].balance also increased by amount.
        // So finalContractBal - initContractBal == sumBalances holds.
        // The mutant fails to add amount to balance, so sumBalances is 0, breaking the equation.
        assertTrue(finalContractBal - initContractBal == sumBalances);
    }
}

