import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint128 _unlockTime, address caller) public {
        vm.assume(caller != address(0));
        // warp to a deterministic non-zero timestamp so block.timestamp is well-defined
        vm.warp(1 ether);
        uint256 u = uint256(_unlockTime);
        // deal some ether to caller so Put can be called with msg.value
        vm.deal(caller, 1 ether);
        vm.prank(caller);
        c.Put{value: 0}(u);

        // The general rule: unlockTime must equal max(u, block.timestamp)
        // block.timestamp is 1 ether from warp; max(u, 1 ether) is u if u > 1 ether else 1 ether
        uint256 expected = u > 1 ether ? u : 1 ether;
        (uint256 storedUnlockTime, ) = c.Acc(caller);
        assertTrue(storedUnlockTime == expected);
    }
}

