contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint128 unlockTime, uint128 amt) public {
        // Ensure unlockTime is in the future, so that the lock is meaningful
        vm.assume(unlockTime > block.timestamp);
