        vm.assume(amt >= 1 ether);

        address user = address(0x1234);
        vm.deal(user, amt);
        vm.prank(user);
        c.Put{value: amt}(unlockTime);

        // Warp to just after block.timestamp but before unlockTime
        vm.warp(block.timestamp + 1);
        vm.assume(block.timestamp < unlockTime);

        // Try to Collect amt - should revert because unlockTime not reached
        bool reverted = false;
        vm.prank(user);
        try c.Collect(amt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assertTrue(reverted);
    }
}

