pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C(address(this));
    }

    function testFuzz_property(uint256 amount1, uint256 amount2, uint256 unlockTime1, uint256 unlockTime2) public {
        // Keep amounts in a reasonable range for fuzzing
        vm.assume(amount1 > 0);
        vm.assume(amount2 > 0);
        vm.assume(amount1 + amount2 >= amount1); // No overflow
        vm.assume(unlockTime1 >= block.timestamp);
        vm.assume(unlockTime2 >= block.timestamp);

        // Use the same caller for both calls
        address caller = address(0x1234);
        vm.deal(caller, amount1 + amount2);

        vm.startPrank(caller);
        c.Put{value: amount1}(unlockTime1);
        c.Put{value: amount2}(unlockTime2);
        vm.stopPrank();

        // After two consecutive Put calls from the same address, the user's balance must be at least the sum of both amounts.
        // In the reference contract, balance = amount1+amount2 (exactly).
        // In the buggy version, balance = amount2 (the second call overwrites).
        (uint accUnlockTime, uint accBalance) = c.Acc(caller);
        assertTrue(accBalance >= amount1 + amount2);
    }
}

