pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 unlockTime, uint256 amount) public {
        // Keep amounts within admissible domain
        amount = bound(amount, 1 ether, 1000 ether);
        unlockTime = bound(unlockTime, block.timestamp, type(uint64).max);

        address actor = address(0x1000);
        vm.deal(actor, amount);
        vm.startPrank(actor);
        c.Put{value: amount}(unlockTime);
        vm.stopPrank();

        // Warp to the exact unlock time (not after)
        vm.warp(unlockTime);

        uint256 balanceBefore = c.Acc(actor).balance;
        vm.prank(actor);
        try c.Collect(amount) {} catch {}
        uint256 balanceAfter = c.Acc(actor).balance;

        // Reference invariant: at block.timestamp == unlockTime, Collect must NOT reduce balance
        // (mutant allows it because >= includes equality, while > excludes equality)
        assertTrue(balanceAfter == balanceBefore);
    }
}

