contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 unlockTime, address actor, uint256 putAmount, uint256 collectAmount) public {
        vm.assume(actor != address(this));
        vm.assume(actor != address(0));
        vm.assume(putAmount >= 1 ether);
        vm.assume(collectAmount >= 1 ether);
        vm.assume(collectAmount <= putAmount);
        vm.assume(unlockTime > block.timestamp + 1);

        vm.deal(actor, putAmount);
        vm.prank(actor);
        c.Put{value: putAmount}(unlockTime);

        vm.warp(unlockTime);

        uint256 balBefore = address(c).balance;
        vm.prank(actor);
        try c.Collect(collectAmount) { } catch { }
        uint256 balAfter = address(c).balance;

        assertTrue(balBefore == balAfter);
    }
